/* v84c - homepage portrait renderer transplanted from luxury-cursor-hero-smooth. Portfolio typography/UI remain separate. */
(()=>{
const BG='#F06326', N=64;
const URLS=["data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,"];
const CENTER="data:image/webp;base64,";
const hero=document.querySelector('[data-character-hero]');if(!hero)return;const canvas=hero.querySelector('[data-character-canvas]');if(!canvas)return;const ctx=canvas.getContext('2d',{alpha:false});
const pointer={x:innerWidth*.5,y:innerHeight*.5},aim={x:pointer.x,y:pointer.y};let imgs=[],centerImg=null,ready=false,angle=Math.PI*1.5;
let faceX=innerWidth*.5,faceY=innerHeight*.31,dead2=0,lastDrawKey=null,lastTs=performance.now();
const TAU=Math.PI*2;const wrap=a=>((a%TAU)+TAU)%TAU;
const angleDelta=(from,to)=>{let d=wrap(to-from);if(d>Math.PI)d-=TAU;return d};
function load(src){return new Promise((res,rej)=>{const im=new Image();im.decoding='async';im.onload=()=>res(im);im.onerror=rej;im.src=src})}
function resize(){const rect=hero.getBoundingClientRect(),vw=Math.max(1,hero.clientWidth),vh=Math.max(1,hero.clientHeight),d=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.round(vw*d);canvas.height=Math.round(vh*d);canvas.style.width=vw+'px';canvas.style.height=vh+'px';ctx.setTransform(d,0,0,d,0,0);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';const sa=1280/720,va=vw/vh;if(va>sa){const sh=vw/sa;faceX=rect.left+vw*.5;faceY=rect.top+sh*.31-(sh-vh)*.5}else{const sw=vh*sa;faceX=rect.left+sw*.5-(sw-vw)*.5;faceY=rect.top+vh*.31}const dead=Math.min(vw,vh)*.12;dead2=dead*dead;lastDrawKey=null;if(ready)draw(centerImg,-1)}
function paint(img,mode='copy',alpha=1){if(!img)return;const vw=Math.max(1,hero.clientWidth),vh=Math.max(1,hero.clientHeight),s=Math.max(vw/img.naturalWidth,vh/img.naturalHeight),w=img.naturalWidth*s,h=img.naturalHeight*s;ctx.globalCompositeOperation=mode;ctx.globalAlpha=alpha;ctx.drawImage(img,(vw-w)/2,(vh-h)/2,w,h)}
function draw(img,key){if(!img||key===lastDrawKey)return;lastDrawKey=key;paint(img,'copy',1);ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over'}
function drawBlend(a,b,mix,key){const q=Math.round(mix*24);const drawKey=`${key}:${q}`;if(drawKey===lastDrawKey)return;lastDrawKey=drawKey;paint(a,'copy',1);if(b&&mix>.015)paint(b,'source-over',mix);ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over'}
function tick(ts){const dt=Math.min(34,Math.max(1,ts-lastTs));lastTs=ts;const pointerEase=1-Math.exp(-dt/58);aim.x+=(pointer.x-aim.x)*pointerEase;aim.y+=(pointer.y-aim.y)*pointerEase;if(ready){const dx=aim.x-faceX,dy=aim.y-faceY;if(dx*dx+dy*dy<dead2){draw(centerImg,-1)}else{const target=wrap(Math.atan2(dy,dx)),delta=angleDelta(angle,target);const tau=Math.abs(delta)>.75?48:72,f=1-Math.exp(-dt/tau);angle=wrap(angle+delta*f);const phase=(wrap(angle+Math.PI/2)/TAU)*N,i0=Math.floor(phase)%N,i1=(i0+1)%N,mix=phase-Math.floor(phase);drawBlend(imgs[i0],imgs[i1],mix,i0)}}requestAnimationFrame(tick)}
const updatePointer=e=>{pointer.x=e.clientX;pointer.y=e.clientY};
if('onpointerrawupdate' in window)hero.addEventListener('pointerrawupdate',updatePointer,{passive:true});else hero.addEventListener('pointermove',updatePointer,{passive:true});
addEventListener('resize',resize,{passive:true});resize();requestAnimationFrame(tick);
Promise.all([...URLS.map(load),load(CENTER)]).then(all=>{imgs=all.slice(0,N);centerImg=all[N];ready=true;lastDrawKey=null;draw(centerImg,-1);hero.dataset.portraitReady='true'}).catch(e=>{console.error(e);hero.dataset.portraitError='true'});

})();

/* Homepage career-highlight rotation retained from the portfolio. */
(()=>{
  'use strict';
  const panel=document.querySelector('[data-hero-kpis]'); if(!panel)return;
  const value=panel.querySelector('[data-hero-kpi-value]'),label=panel.querySelector('[data-hero-kpi-label]'),count=panel.querySelector('[data-hero-kpi-count]');
  if(!value||!label||!count)return;
  const items=[['200+','customers supported by systems I’ve worked on'],['2 weeks → 2 hours','customer-reported deployment time to value'],['1,050 min','mentoring across four countries'],['2022','AppDynamics hackathon-winning experiment']];
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');let index=0,timer=0;
  const render=next=>{index=next%items.length;const [v,l]=items[index];panel.classList.add('is-changing');setTimeout(()=>{value.textContent=v;label.textContent=l;count.textContent=`${String(index+1).padStart(2,'0')} / ${String(items.length).padStart(2,'0')}`;panel.classList.remove('is-changing')},reduced.matches?0:180)};
  const stop=()=>{if(timer)clearInterval(timer);timer=0}; const start=()=>{stop();if(reduced.matches||document.hidden)return;timer=setInterval(()=>render(index+1),3600)};
  reduced.addEventListener('change',start);document.addEventListener('visibilitychange',()=>document.hidden?stop():start());window.addEventListener('pagehide',stop,{once:true});start();
})();
